# %% ../nbs/01_htmx_bridge.ipynb #a78cb5ac
_loaded = False
async def setup_htmx_bridge(debugger:bool=False):
    "Inject htmx bridge into the browser"
    global _loaded
    txt = (resources.files('dutil')/'hx_bridge.js').read_text()
    await iife_a(f"{'debugger;\n' if debugger else ''}"+txt)
    _loaded = True

# %% ../nbs/01_htmx_bridge.ipynb #a6d400ce
class HTMX:
    "A proxy for the htmx JS API"
    async def __call__(self, method, *args, full_response=False, timeout=10, _retry=True):
        "Low-level async call to htmx JS API"
        msgid = (await read_msg()).id
        res = await event_get_a('hx_bridge', timeout=timeout, data=dict(method=method, args=args, full_response=full_response, msgid=msgid))
        try: del res['data_id']
        except KeyError: pass
        if res is None:
            if not _loaded and _retry:
                await setup_htmx_bridge()
                return await self(method, *args, full_response=full_response, timeout=timeout, _retry=False)
            return AD(error=f"htmx bridge returned no response for '{method}'")
        return res if full_response else res.success if 'success' in res else res

