@patch
@delegates(HTMX.__call__)
async def swap(self:HTMX, target, content, swapSpec=None, swapOptions=None, **kwargs):
    "Perform an htmx swap, blocking until complete"
    if not isinstance(content, str): content = to_xml(content)
    spec = dict(swapStyle='innerHTML', scroll=False, show=False) | (swapSpec or {})
    return await self('swap', target, content, spec, swapOptions or {}, **kwargs)

